import json
with open('/app/examples.json') as f:
    examples = json.load(f)
for idx, ex in enumerate(examples):
    inp = ex['input']
    out = ex['output']
    distinct = []
    # iterate over i+j from 0 to 12
    for s in range(13):
        # i from max(0, s-6) to min(6, s)
        for i in range(max(0, s-6), min(6, s)+1):
            j = s - i
            v = inp[i][j]
            if v != 0 and v not in distinct:
                distinct.append(v)
    pattern = [out[0][0], out[0][1], out[0][2]]
    print(f'Example {idx+1}: distinct by anti-diagonal order: {distinct}')
    print('  pattern:', pattern)
    if distinct == pattern:
        print('  MATCH')
    else:
        # try rotation
        for rot in range(3):
            if pattern == distinct[rot:] + distinct[:rot]:
                print(f'  rotation offset {rot}')
                break
        else:
            print('  no match')
